ValidationRule.errorConditionFormula:
AND(
   $RecordType.DeveloperName = "ACCTrial",

    OR(

        AND(
            ISPICKVAL(Status, "Closed"),
            ISBLANK(Executive_Summary__c)
        ),


        AND(
            ISPICKVAL(PRIORVALUE(Status), "Closed"),
            NOT(ISCHANGED(Status))
        )
    )
)
